(function(root){
const companies=['플랜티넷','플랜티엠'];
const headers=['회사명','이름','근무부서','직급','성별','생년월일','입사일','퇴사일','고용형태','연봉'];
const jobHeaders=[...headers,'직군'];
function date(v){if(v==null||v==='')return null;if(v instanceof Date){if(isNaN(v))return 'INVALID';return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;}if(typeof v==='number'){const d=new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000);return d.toISOString().slice(0,10);}const s=String(v).trim();const m=s.match(/^(\d{4})[-./년\s]?(\d{1,2})[-./월\s]?(\d{1,2})일?$/);if(!m)return 'INVALID';const y=+m[1],mo=+m[2],d=+m[3];const dt=new Date(Date.UTC(y,mo-1,d));if(dt.getUTCFullYear()!==y||dt.getUTCMonth()+1!==mo||dt.getUTCDate()!==d)return 'INVALID';return `${m[1]}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;}
function years(from,to){if(!from||from>to)return null;const a=from.split('-').map(Number),b=to.split('-').map(Number);return b[0]-a[0]-((b[1]<a[1]||(b[1]===a[1]&&b[2]<a[2]))?1:0);}
function normalize(records){let errors=[],warnings=[],seen=new Set(),rows=[];records.forEach((raw,i)=>{const r={};Object.entries(raw).forEach(([k,v])=>r[String(k).replace(/\s/g,'')]=v);if(!Object.entries(r).some(([k,v])=>k!=='__source'&&v!==''&&v!=null))return;const line=raw.__source||`${i+2}행`;const company=String(r['회사']||r['회사명']||'').trim();const id=String(r['사번']??'').trim();const name=String(r['이름']||r['성명']||'').trim();if(!companies.includes(company))errors.push(`${line}: 회사명은 플랜티넷 또는 플랜티엠으로 입력하세요.`);if(!name)errors.push(`${line}: 이름이 필요합니다.`);const birth=date(r['생년월일']),join=date(r['입사일']),leave=date(r['퇴사일']);if(!join||join==='INVALID')errors.push(`${line}: 입사일을 YYYY-MM-DD로 확인하세요.`);if(birth==='INVALID'||leave==='INVALID')errors.push(`${line}: 생년월일 또는 퇴사일이 잘못되었습니다.`);if(leave&&join&&leave<join)errors.push(`${line}: 퇴사일이 입사일보다 빠릅니다.`);if(birth&&join&&birth>join)errors.push(`${line}: 생년월일이 입사일보다 늦습니다.`);const sal=r['연봉']??r['연봉(원)']??r['연봉(만원)'];let salary=sal==null||String(sal).trim()===''?null:Number(String(sal).replace(/[,₩원\s]/g,''));if(r['연봉(만원)']!=null&&r['연봉']==null&&r['연봉(원)']==null&&salary!==null)salary*=10000;if(salary!==null&&(!Number.isFinite(salary)||salary<0))errors.push(`${line}: 연봉은 0 이상의 숫자(원 단위)로 입력하세요.`);const g=String(r['성별']||'').trim().toLowerCase();const gender=['남','남성','m','male','남자'].includes(g)?'남성':['여','여성','f','female','여자'].includes(g)?'여성':'미입력/기타';const row={company,id,name,birth,join,leave,gender,department:String(r['근무부서']||r['부서']||'미입력').trim(),rank:String(r['직급']||'미입력').trim(),type:String(r['고용형태']||'미입력').trim(),salary,family:String(r['직군']||'').trim()||'미분류'};const key=JSON.stringify({...row,id:''});if(seen.has(key))warnings.push(`${line}: 모든 입력값이 같은 중복 의심 행입니다. 자동 삭제하지 않고 별도 인원으로 집계합니다.`);seen.add(key);rows.push(row);});if(!rows.length)errors.push('인사자료 행이 없습니다. 빈 양식에는 데이터를 입력해 주세요.');return {rows,errors,warnings};}
function active(rows,asof,company='전체'){return rows.filter(r=>(company==='전체'||r.company===company)&&r.join<=asof&&(!r.leave||r.leave>asof));}
function summary(rows,asof){const salaries=rows.filter(r=>r.salary!==null).map(r=>r.salary).sort((a,b)=>a-b),ages=rows.map(r=>years(r.birth,asof)).filter(x=>x!==null),tenures=rows.map(r=>years(r.join,asof));const total=salaries.reduce((a,b)=>a+b,0);return {count:rows.length,total,paid:salaries.length,average:salaries.length?total/salaries.length:null,median:salaries.length?(salaries[Math.floor((salaries.length-1)/2)]+salaries[Math.floor(salaries.length/2)])/2:null,age:ages.length?ages.reduce((a,b)=>a+b,0)/ages.length:null,ageN:ages.length,tenure:tenures.length?tenures.reduce((a,b)=>a+b,0)/tenures.length:null};}
function distribution(rows,asof,kind){const labels=kind==='tenure'?['10년 이상','5~10년 미만','3~5년 미만','1~3년 미만','1년 미만']:['50세 이상','40대','30대','20대','20세 미만','미입력'];const counts=labels.map(()=>0);rows.forEach(r=>{const y=years(kind==='tenure'?r.join:r.birth,asof);let n;if(kind==='tenure')n=y>=10?0:y>=5?1:y>=3?2:y>=1?3:4;else n=y===null?5:y>=50?0:y>=40?1:y>=30?2:y>=20?3:4;counts[n]++;});return labels.map((label,i)=>({label,count:counts[i]})).filter(x=>kind==='tenure'||!['20세 미만','미입력'].includes(x.label)||x.count>0);}
function ranks(rows,asof){const order=['임원','사장','부사장','전무','상무','이사','부장','차장','과장','대리','주임','사원','미입력'];return [...new Set(rows.map(r=>r.rank))].sort((a,b)=>(order.includes(a)?order.indexOf(a):99)-(order.includes(b)?order.indexOf(b):99)||a.localeCompare(b,'ko')).map(rank=>({rank,...summary(rows.filter(r=>r.rank===rank),asof)}));}
function changes(current,previous,asof,prevAsOf,company='전체'){const cur=active(current,asof,company),prev=active(previous,prevAsOf,company);const key=r=>JSON.stringify([r.company,r.name,r.birth,r.join]);const group=rows=>{const map=new Map();rows.forEach(r=>{const k=key(r);if(!map.has(k))map.set(k,[]);map.get(k).push(r);});return map;};const cm=group(cur),pm=group(prev),allCurrent=group(current);const added=[],removed=[],changed=[],unresolvedCurrent=[],unresolvedPrevious=[];for(const k of new Set([...cm.keys(),...pm.keys()])){const a=cm.get(k)||[],b=pm.get(k)||[];if(a.length>1||b.length>1||!(a[0]||b[0]).birth){unresolvedCurrent.push(...a);unresolvedPrevious.push(...b);continue;}if(a.length&&b.length){const before=b[0],after=a[0],fields=[['department','근무부서'],['rank','직급'],['family','직군'],['type','고용형태'],['salary','연봉']].filter(([field])=>before[field]!==after[field]).map(([field,label])=>({field,label,before:before[field],after:after[field]}));if(fields.length)changed.push({before,after,fields});}else if(a.length){const row=a[0];added.push({row,reason:row.join>prevAsOf&&row.join<=asof?'기간 내 입사일 확인':'이번 자료에만 포함 · 사유 확인 필요'});}else{const row=b[0],ledger=(allCurrent.get(k)||[]);const leaver=ledger.length===1&&ledger[0].leave>prevAsOf&&ledger[0].leave<=asof;removed.push({row,reason:leaver?`기간 내 퇴사일 확인 (${ledger[0].leave})`:'이전 자료에만 포함 · 사유 확인 필요'});}}return {current:cur.length,previous:prev.length,delta:cur.length-prev.length,added,removed,changed,unresolvedCurrent,unresolvedPrevious};}
root.People={companies,headers,jobHeaders,date,years,normalize,active,summary,distribution,ranks,changes};if(typeof module!=='undefined')module.exports=root.People;
})(typeof window==='undefined'?globalThis:window);
